// Instanzwerte aus sub-einstellungen (Data Table pw_config, gepflegt in der
// n8n-Oberfläche unter "Data Tables").
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return String(v).trim();
};

// Das Ereignis von Paper-Werk (docs/webhooks.md in paper-werk-app).
const ereignis = $('Webhook').first().json.body ?? {};
const beleg = ereignis.beleg ?? {};

// Fachlich: welche Paare aus Typ und Aktion in den Chat gehen.
const MELDEN = [
  ['auftrag', 'angelegt'],
  ['auftrag', 'festgeschrieben'],
  ['rechnung', 'versendet'],
];

if (!MELDEN.some(([typ, aktion]) => typ === beleg.typ && aktion === ereignis.aktion)) return [];

const format = String(werte.chat_format ?? '').trim() || 'text';
if (!['text', 'teams'].includes(format)) {
  throw new Error('pw_config: chat_format "' + format + '" ist unbekannt; erlaubt sind "text" und "teams".');
}
return [{ json: {
  chat_webhook_url: pw('chat_webhook_url'),
  chat_format: format,
  aktion: ereignis.aktion,
  beleg,
} }];

const euro = (v) => Number(v ?? 0).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
const datum = (iso) => (iso ? String(iso).slice(0, 10).split('-').reverse().join('.') : '');
const html = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const TYPEN_TEXT = { angebot: 'Angebot', auftrag: 'Auftrag', lieferschein: 'Lieferschein', rechnung: 'Rechnung', storno: 'Stornorechnung', gutschrift: 'Rechnungskorrektur', mahnung: 'Mahnung' };
const typText = (typ) => TYPEN_TEXT[typ] ?? typ;

const cfg = $input.first().json;
const b = cfg.beleg;
const kunde = b.kunde?.name ?? 'ohne Kunde';
const projekt = b.projekt ? ` (Projekt ${b.projekt.nummer} ${b.projekt.bezeichnung})` : '';

let zeile;
if (b.typ === 'auftrag' && cfg.aktion === 'angelegt' && b.vorgaenger?.typ === 'angebot') {
  zeile = `Angebot ${b.vorgaenger.nummer} angenommen: neuer Auftrag für ${kunde}${projekt} über ${euro(b.brutto)}.`;
} else if (b.typ === 'auftrag' && cfg.aktion === 'angelegt') {
  zeile = `Neuer Auftrag (Entwurf) für ${kunde}${projekt}.`;
} else if (b.typ === 'auftrag' && cfg.aktion === 'festgeschrieben') {
  zeile = `Auftrag ${b.nummer} für ${kunde}${projekt} bestätigt: ${euro(b.brutto)}.`;
} else if (b.typ === 'rechnung' && cfg.aktion === 'versendet') {
  zeile = `Rechnung ${b.nummer} an ${kunde}${projekt} versendet: ${euro(b.brutto)}, fällig am ${datum(b.faellig_am)}.`;
} else {
  zeile = `${typText(b.typ)} ${b.nummer ?? '(Entwurf)'} für ${kunde}: ${cfg.aktion}.`;
}

const nachricht = cfg.chat_format === 'teams'
  ? { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', content: {
      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
      body: [{ type: 'TextBlock', text: zeile, wrap: true }],
      actions: b.admin_url ? [{ type: 'Action.OpenUrl', title: 'In Paper-Werk öffnen', url: b.admin_url }] : [],
    } }] }
  : { text: b.admin_url ? `${zeile}\n${b.admin_url}` : zeile };

return [{ json: { url: cfg.chat_webhook_url, nachricht } }];
